/**
 * The built bundle, for tests that need real data.
 *
 * `app/public/data/bundle.json` is generated by `tools/ef/export.py` and not
 * under version control. Locally a missing bundle skips these tests; in CI
 * `REQUIRE_BUNDLE=1` turns the skip into a failure, so a green run there
 * means the whole suite ran, not a third of it.
 *
 * Tests must not read the roster from the bundle: it is a snapshot of one
 * account that changes as the account levels up, and the public bundle has
 * none. Teams are built here from explicit specs instead.
 */

import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

import { describe, it } from 'vitest';

import { assertBundle, type Bundle, type RotStep, type TeamMember } from '../../src/index.js';

export const BUNDLE_PATH = fileURLToPath(new URL('../../../app/public/data/bundle.json', import.meta.url));

function load(): Bundle | null {
  if (!existsSync(BUNDLE_PATH)) {
    if (process.env.REQUIRE_BUNDLE === '1') {
      throw new Error(`REQUIRE_BUNDLE=1, but there is no ${BUNDLE_PATH}. Run: python3 tools/ef/export.py`);
    }
    return null;
  }
  const payload: unknown = JSON.parse(readFileSync(BUNDLE_PATH, 'utf8'));
  assertBundle(payload);
  return payload;
}

export const bundle: Bundle | null = load();

/**
 * A `describe` that receives the bundle, or is skipped without it.
 *
 * `describe.skip` still runs its body while collecting tests, so a body that
 * touches `bundle!` at the top crashes the file instead of skipping it. Here
 * the body never runs without a bundle.
 */
export function describeWithBundle(name: string, body: (data: Bundle) => void): void {
  if (bundle) {
    describe(name, () => body(bundle));
  } else {
    describe.skip(name, () => {
      it('needs the bundle: python3 tools/ef/export.py', () => {});
    });
  }
}

export interface MemberSpec {
  level: number;
  elite: number;
  skills: TeamMember['skills'];
}

/** Level 90, elite 4, every skill at 12: what the golden builds assume. */
export const MAXED: MemberSpec = {
  level: 90,
  elite: 4,
  skills: { basic: 12, battle: 12, combo: 12, ultimate: 12 },
};

/**
 * A team in team-position order: `order` first, then whoever acts in `steps`
 * but is not listed — the same rule as `teamFromRoster`, without the roster.
 * Keys the bundle does not know are left out, as there.
 */
export function teamOf(
  data: Bundle,
  order: string[],
  steps: RotStep[] = [],
  specs: Record<string, MemberSpec> = {},
  fallback: MemberSpec = MAXED,
): Map<string, TeamMember> {
  const team = new Map<string, TeamMember>();
  const keys = [...order, ...steps.flatMap((step) => (step.actor ? [step.actor] : []))];
  for (const [index, key] of keys.entries()) {
    const operator = data.operators[key];
    if (team.has(key) || !operator) continue;
    const spec = specs[key] ?? fallback;
    // An empty slot (`''`) in `order` keeps the positions after it.
    const slot = index < order.length ? { slot: index + 1 } : {};
    team.set(key, { key, ...slot, operator, level: spec.level, elite: spec.elite, skills: { ...spec.skills } });
  }
  return team;
}
